DROP POLICY mentor_profile_read ON public.profiles; ALTER POLICY profile_read ON public.profiles USING(id=(select auth.uid()) OR (employer_visible AND (select public.has_role((select auth.uid()),'employer'))) OR (select public.has_role((select auth.uid()),'admin')) OR id IN(SELECT seeker_id FROM public.mentorships WHERE mentor_id IN(SELECT id FROM public.mentor_listings WHERE user_id=(select auth.uid()))));
CREATE FUNCTION public.guard_mentorship() RETURNS trigger LANGUAGE plpgsql SET search_path=public AS $$ BEGIN IF NEW.seeker_id IS DISTINCT FROM OLD.seeker_id OR NEW.mentor_id IS DISTINCT FROM OLD.mentor_id THEN RAISE EXCEPTION 'Cannot change mentorship participants'; END IF; RETURN NEW; END $$; CREATE TRIGGER mentorship_guard BEFORE UPDATE ON public.mentorships FOR EACH ROW EXECUTE FUNCTION public.guard_mentorship();
CREATE POLICY career_upload_insert ON storage.objects FOR INSERT TO authenticated WITH CHECK(bucket_id IN('career-documents','profile-photos') AND (storage.foldername(name))[1]=(select auth.uid())::text);
CREATE POLICY career_upload_update ON storage.objects FOR UPDATE TO authenticated USING(bucket_id IN('career-documents','profile-photos') AND (storage.foldername(name))[1]=(select auth.uid())::text) WITH CHECK(bucket_id IN('career-documents','profile-photos') AND (storage.foldername(name))[1]=(select auth.uid())::text);
CREATE POLICY career_upload_delete ON storage.objects FOR DELETE TO authenticated USING(bucket_id IN('career-documents','profile-photos') AND (storage.foldername(name))[1]=(select auth.uid())::text);
CREATE POLICY career_upload_read ON storage.objects FOR SELECT TO authenticated USING((bucket_id IN('career-documents','profile-photos') AND (storage.foldername(name))[1]=(select auth.uid())::text) OR (bucket_id='career-documents' AND name IN(SELECT cv_path FROM public.profile_documents)) OR (bucket_id='profile-photos' AND name IN(SELECT avatar_url FROM public.profiles)));